{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Mithramycin, a large glycosylated polyketide with multiple sugars and polar groups, showed a peak CSF:plasma ratio of only 0.12 in monkeys and was classified as poor brain penetration; this direct CSF measurement transfers to the query's large, polar anthracycline glycoside scaffold and supports limited CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "DX-52-1, a polar fused polycyclic with ionizable groups, had a brain-to-blood ratio of about 0.02 in mice by quantitative autoradioluminography, directly demonstrating that this class of polar polycyclic agents does not achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Digitoxin, a cardiac glycoside, exhibited a very low CSF/plasma ratio (0.01-0.03) in dogs and was classified as impermeable, providing direct evidence that glycosylated natural products with large polar surfaces are poorly CNS-penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "SC-4453, a cardiac glycoside, had the lowest brain concentration (1.2 ng/g) at steady state in guinea-pigs, confirming a blood-brain barrier to this glycoside class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Emodin-8-O-β-D-glucoside, an anthraquinone glycoside, distributed into rat brain in a dose-dependent manner and was classified as BBB-permeable; this is the closest positive glycoside analogue, but its smaller size, neutral glucose, and enhancement by ischemia/reperfusion limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted fail: the doxorubicin-like anthracycline glycoside has very low passive permeability and is a known P-gp substrate; direct CSF/T/B evidence from similar glycosylated polyketides and polar polycyclics shows poor CNS access, and cyclosporine co-treatment is unlikely to overcome the passive permeability barrier.",
  "evidence_gaps": [
    "No direct brain/CSF measurement for the query itself under cyclosporine co-treatment; transfer relies on analogues.",
    "Cyclosporine co-treatment may alter P-gp/BCRP efflux, but no analogue evidence with cyclosporine is available.",
    "Positive glycoside brain-penetration records may reflect hydrolysis or BBB disruption rather than intact compound exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

